// Capped batch fill. Pick up to MAX planned fb_content_plan slots (plan_date >= today, no
// fb_posts row yet), oldest first, and pre-build each slot's generator prompt. All Supabase
// reads happen here via this.helpers.httpRequest so PostgREST arrays don't fan out. Emits ONE
// control item carrying the chosen slots array (empty array when there is nothing to fill).
const body = $('Webhook (fb-generate-batch)').first().json.body || {};
const MAX = 7;
let max = Number(body.max || MAX);
if (!(max > 0)) max = MAX;
max = Math.min(max, MAX);
const today = $now.toFormat('yyyy-LL-dd');
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const planned = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_content_plan?status=eq.planned&plan_date=gte.' + today + '&select=id,plan_date,pillar,archetype,subtopic_id,brief,brief_status&order=plan_date.asc', headers: h, json: true });
const posts = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_posts?select=scheduled_date&scheduled_date=gte.' + today, headers: h, json: true });
const taken = new Set((posts || []).map(p => p.scheduled_date));
const subs = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_subtopics?select=id,subtopic,pillar,times_used', headers: h, json: true });
const subById = Object.fromEntries((subs || []).map(s => [s.id, s]));
const prompts = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_messaging_prompts?is_active=eq.true&select=name,body', headers: h, json: true });
const byName = Object.fromEntries((prompts || []).map(p => [p.name, p.body]));
const bankArr = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_message_bank?is_active=eq.true&select=variables&limit=1', headers: h, json: true });
const bank = (bankArr && bankArr[0] && bankArr[0].variables) || {};

// Visual variety: rotate the scene type by each slot's plan date, and remember recent
// image concepts so the image stage can steer away from repeating the same scene.
const VISUAL_ANGLES = [
  'extreme close-up of impact-glass or frame hardware detail — product macro, no people',
  'a beautiful Florida home exterior with new impact windows — curb appeal, crisp morning light',
  'a bright, light-filled interior room seen through large impact windows',
  'a happy homeowner or family moment at home — relaxed, confident, smiling',
  'an installer or craftsman fitting a window — skilled hands, pride in the work',
  'a dramatic storm sky over a Florida neighborhood — homes standing strong, no people',
  'a coastal Florida scene — palms, water, homes built for the climate',
  'macro of rain streaming down impact glass while the interior beyond stays warm and dry'
];
const TIMES = ['bright mid-morning','clear midday','fresh early morning','blue hour just after sunset','bright overcast early afternoon','breezy late morning'];
const PALETTES = ['crisp whites and coastal blues','airy neutrals with tropical green accents','clean daylight with soft teal and sand tones','cool blues with a single warm lamp accent','fresh whites, greys, and palm greens','vivid sunny tropical color, saturated and cheerful'];
let recentRows = [];
try { recentRows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_posts?select=image_concept&image_concept=not.is.null&status=neq.skipped&scheduled_date=gte.' + today + '&order=scheduled_date.asc&limit=12', headers: h, json: true }); } catch (e) {}
const recent_scenes = (recentRows || []).map(r => String(r.image_concept || '').slice(0, 140)).filter(Boolean).join(' ; ') || 'none yet';

// Text-only mix: same deterministic fb_settings.text_share date rotation as WF1 (keyed to
// plan_date, so nightly and batch fills agree on which dates go text-only).
let text_share = 25;
try { const ts = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_settings?id=eq.1&select=text_share', headers: h, json: true }); if (ts && ts[0] && ts[0].text_share !== null && ts[0].text_share !== undefined) text_share = ts[0].text_share; } catch (e) {}
const system = byName['style_guide'] || '';
const chosen = (planned || []).filter(s => !taken.has(s.plan_date)).slice(0, max);
const slots = chosen.map(s => {
  const st = subById[s.subtopic_id] || {};
  // Strategist brief (only when the slot carries an APPROVED brief); else Phase 1 image-only
  // fallbacks. media_type forced to image / video_concept empty until the video branch lands.
  const brief = (s.brief_status === 'approved' && s.brief) ? s.brief : null;
  const pillarFinal = (brief && brief.pillar) ? brief.pillar : (s.pillar || st.pillar || '');
  const buyerStage = (brief && brief.funnel_stage) ? brief.funnel_stage : '#1';
  const buyerObjective = (brief && brief.buyer_objective) ? brief.buyer_objective : 'education';
  const captionDirection = (brief && brief.caption_direction) ? brief.caption_direction : '';
  const recommendedCta = (brief && brief.recommended_cta) ? brief.recommended_cta : 'soft: end with one engagement question';
  const imageConcept = (brief && brief.image_concept) ? brief.image_concept : '';
  const angleDay = Math.floor(Date.parse(s.plan_date + 'T12:00:00Z') / 86400000);
  const visual_angle = VISUAL_ANGLES[angleDay % VISUAL_ANGLES.length] + ' — shot at ' + TIMES[(angleDay * 5 + 1) % TIMES.length] + '; palette: ' + PALETTES[(angleDay + 2) % PALETTES.length];
  const media_type = (text_share > 0 && (angleDay % Math.max(2, Math.round(100 / text_share)) === 0)) ? 'text' : 'image';
  // Image template per slot: resolve everything except {{image_concept}}/{{post_body}} —
  // the image node fills those in after the generator returns them.
  const image_template = (byName['image'] || '')
    .replaceAll('{{visual_angle}}', visual_angle)
    .replaceAll('{{recent_scenes}}', recent_scenes)
    .replaceAll('{{image_feedback}}', 'none');
  const user = (byName['generator'] || '')
    .replaceAll('{{style_guide}}', system)
    .replaceAll('{{message_bank}}', JSON.stringify(bank))
    .replaceAll('{{pillar}}', pillarFinal)
    .replaceAll('{{archetype}}', s.archetype || '')
    .replaceAll('{{subtopic}}', st.subtopic || '')
    .replaceAll('{{buyer_stage}}', buyerStage)
    .replaceAll('{{buyer_objective}}', buyerObjective)
    .replaceAll('{{caption_direction}}', captionDirection)
    .replaceAll('{{media_type}}', media_type)
    .replaceAll('{{image_concept}}', imageConcept)
    .replaceAll('{{video_concept}}', '')
    .replaceAll('{{recommended_cta}}', recommendedCta)
    .replaceAll('{{visual_angle}}', visual_angle)
    .replace(/\{\{[^}]+\}\}/g, '');
  return { plan_id: s.id, plan_date: s.plan_date, pillar: pillarFinal, archetype: s.archetype, subtopic_id: s.subtopic_id || null, times_used: st.times_used || 0, system, user, visual_angle, image_template, media_type };
});
return [{ json: { slots } }];

// Tolerant JSON parse of the generator object { post_body, first_comment, image_concept, ... }.
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let out;
try { out = JSON.parse(t); } catch (e) { const m = t.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : {}; }
return [{ json: out }];

// Decode the gpt-image-1 base64 into an n8n binary property for the Upload node. The two-node
// path (prepareBinaryData -> HTTP node contentType:binaryData) is the ONLY reliable upload in this
// n8n build: this.helpers.httpRequest({ body: buf }) serializes the Buffer to {"type":"Buffer",...}
// text even with json:false. We also compute the final public image_url here so the Insert node can
// read it back via $('Decode Image').item without depending on the upload node's response body.
const b64 = $json.data?.[0]?.b64_json;
if (!b64) throw new Error('Image generation returned no b64_json');
const buf = Buffer.from(b64, 'base64');
if (buf.length < 1000) throw new Error('Decoded image too small (' + buf.length + ' bytes) - failed generation');
const SB = '__SUPABASE_URL__';
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.png`;
return [{ json: { path, image_url: SB + '/storage/v1/object/public/fb-images/' + path }, binary: { data: await this.helpers.prepareBinaryData(buf, path, 'image/png') } }];

// Throttle ~3s between slots so Anthropic / image / GroupMe don't rate-limit. Passes items through.
await new Promise(r => setTimeout(r, 3000));
return $input.all();
